previewCss:
.darma-loader-darma-b15-swipe-card-stack { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #fecdd3); width: var(--loader-size, 118px); height: calc(var(--loader-size, 118px) * .74); position: relative; overflow: hidden; border-radius: 14px; }
.darma-loader-darma-b15-swipe-card-stack span { position: absolute; left: 16%; right: 16%; top: 6%; bottom: 18%; border-radius: 12px; background: linear-gradient(150deg, var(--accent), color-mix(in srgb, #000 22%, var(--accent))); box-shadow: 0 6px 14px color-mix(in srgb, #000 22%, transparent); animation: darma-loader-darma-b15-swipe-card-stack-deck-swipe calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b15-swipe-card-stack span::after { content: ''; position: absolute; left: 12%; right: 40%; top: 16%; height: 12%; border-radius: 4px; background: color-mix(in srgb, var(--accent-2) 70%, transparent); }
.darma-loader-darma-b15-swipe-card-stack span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * -2); }
.darma-loader-darma-b15-swipe-card-stack span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * -1); }
@keyframes darma-loader-darma-b15-swipe-card-stack-deck-swipe { 0% { transform: translate(0, 0) rotate(0deg) scale(1); opacity: 1; } 18% { transform: translate(150%, -12%) rotate(20deg) scale(1); opacity: 0; } 22% { transform: translate(0, 16%) rotate(0deg) scale(.82); opacity: 0; } 40% { transform: translate(0, 16%) rotate(0deg) scale(.82); opacity: .5; } 70% { transform: translate(0, 8%) rotate(0deg) scale(.91); opacity: .8; } 100% { transform: translate(0, 0) rotate(0deg) scale(1); opacity: 1; } }

